async ({ workspace: { read, glob }, git: { status, log } }) => {
  const [pkg, files, st, lg, contrib] = await Promise.all([
    read("package.json", { format: "raw" }),
    glob(["**/*", "!node_modules/**", "!dist/**"], { limit: 200 }),
    status(["--short", "--branch"]),
    log(["--oneline", "-10"]),
    read("CONTRIBUTING.md", { format: "raw" }),
  ]);
